"""Source-backed background chapters; no application or mission-state changes."""
from reportlab.platypus import Flowable, Spacer
from reportlab.lib.colors import HexColor

class FuelBalance(Flowable):
    """Exact illustration of rounded Sentinel accounting values, not tank geometry."""
    def __init__(self,de):
        Flowable.__init__(self);self.width=499;self.height=118;self.de=de
    def draw(self):
        c=self.canv
        rows=[('FOB IN','6,256',6256,'#54624b'),('GROSS ONLOAD','+966',966,'#81965e'),('AAR BURN','-324',324,'#9b7951'),('NET GAIN','+642',642,'#81965e'),('FOB OUT','6,898',6898,'#24302e')]
        for i,(label,number,value,color) in enumerate(rows):
            y=98-i*23;c.setFont('Bold',8);c.setFillColor(HexColor('#24302e'));c.drawString(0,y+4,label)
            c.setFillColor(HexColor(color));c.rect(112,y,max(4,value/7213*315),14,fill=1,stroke=0)
            c.setFillColor(HexColor('#24302e'));c.setFont('Mono',9);c.drawRightString(499,y+3,(number.replace(',','.') if self.de else number)+' kg')

def add_background(g,lang):
    S,page,p,h,box,table,formula=[g[k] for k in ('S','page','p','h','box','table','formula')]
    de=lang=='de'
    def tr(a,b):return a if de else b
    page(15,tr('AAR: Ort, Zeitpunkt, Ablauf','AAR: position, time, sequence'),tr('ARIP, ARCP und ARCT lösen ein Rendezvous-Problem, keine Fuel-Rechnung.','ARIP, ARCP and ARCT coordinate a rendezvous, not a fuel calculation.'))
    p(tr('Tanker und Receiver müssen räumlich und zeitlich zusammenkommen. Die drei Angaben beantworten unterschiedliche Fragen. Die hier verwendeten Begriffe stammen aus öffentlich zugänglichen US-/zivilen Unterlagen; das konkrete Verfahren wird im jeweiligen Briefing festgelegt. [1, 2]','Tanker and receiver have to meet in space and time. The three entries answer different questions. The terminology below comes from public US/civil aviation documents; the specific procedure is established in the applicable briefing. [1, 2]'))
    table([
      ('ARIP',tr('<b>Wo beginnt das Rendezvous?</b><br/>Air Refuelling Initial Point: vorgelagerter geografischer Anfangspunkt. Er strukturiert den Einflug zum Treffen mit dem Tanker. [1]','<b>Where does the rendezvous begin?</b><br/>Air Refuelling Initial Point: an upstream geographical starting point that structures the entry towards the tanker rendezvous. [1]')),
      ('ARCP',tr('<b>Wo soll die Formation zusammenfinden?</b><br/>Air Refuelling Control Point: geplanter Ort, an dem der Receiver relativ zum Tanker die Beobachtungs-/Pre-contact-Position erreicht. Das bedeutet noch keinen Fuel-Transfer. [1]','<b>Where should the formation come together?</b><br/>Air Refuelling Control Point: planned location where the receiver reaches the observation/pre-contact position relative to the tanker. Fuel need not be flowing yet. [1]')),
      ('ARCT',tr('<b>Wann wird dieses Treffen geplant?</b><br/>Air Refuelling Control Time: zeitlicher Rendezvous-Bezug. Beim Point-parallel-Verfahren auf den ARCP bezogen, beim Enroute-Rendezvous auf den ARIP. Also nicht immer pauschal die Uhrzeit am ARCP. [1]','<b>When is that meeting planned?</b><br/>Air Refuelling Control Time: the rendezvous time reference. It applies to the ARCP for a point-parallel rendezvous and to the ARIP for an enroute rendezvous. It is not universally the time at ARCP. [1]')),
    ],[65,434],[tr('ANGABE','ENTRY'),tr('PRAKTISCHE BEDEUTUNG','PRACTICAL MEANING')])
    h(tr('Warum das wichtig ist','Why it matters'))
    p(tr('Ankunft im Betankungsraum, Zusammenfinden, stabiler Kontakt, Fuel-Transfer und Verlassen des Events sind verschiedene Vorgänge. In realen Verfahren gehören auch Luftraumkoordination und Freigaben dazu; ein erreichter Zeitpunkt allein erlaubt noch keine Betankung. Deshalb sind ARCT und die tatsächliche Zeit mit fließendem Fuel nicht austauschbar. [2]','Arrival in the refuelling area, rendezvous, stable contact, fuel flow and leaving the event are different stages. Real procedures also involve airspace coordination and clearances; reaching a time alone does not authorize refuelling. ARCT and time with fuel flowing are therefore not interchangeable. [2]'))
    h(tr('So bildet die App das ab','How the app represents it'))
    p(tr('<b>AAR after waypoint</b> setzt das berechnete Ereignis in die Route. Der Bon zeigt als ARCT die berechnete Ankunft dort. <b>ARCT PLAN / AAR OUT PLAN</b> sind Vergleichswerte; sie ersetzen keinen Hard-Time-Eintrag in der Route. ARIP/ARCP-Textfelder erzeugen weder zusätzliche Legs noch ein Rendezvous-Manöver. [7]','<b>AAR after waypoint</b> locates the calculated event on the route. The ticket shows the calculated arrival there as ARCT. <b>ARCT PLAN / AAR OUT PLAN</b> are comparison entries, not substitutes for route hard times. ARIP/ARCP text fields create neither extra legs nor a rendezvous manoeuvre. [7]'))
    box('SENTINELLE / RP ANGIE',tr('ARIP bleibt NOT DEFINED, weil kein Punkt geliefert wurde. RP ANGIE ist die eingetragene ARCP-Referenz. 17:50Z bis 18:00Z ist der geplante AAR-Block; daraus folgt nicht, dass zehn Minuten lang Kraftstoff übertragen wird.','ARIP remains NOT DEFINED because no point was supplied. RP ANGIE is the entered ARCP reference. 17:50Z to 18:00Z is the planned AAR block; this does not imply ten minutes of fuel transfer.'))

    page(16,tr('Gross, Net und Fuel on Board','Gross, net and fuel on board'),tr('Die Triebwerke laufen während der Betankung weiter. Deshalb sind Lieferung und Zuwachs verschieden.','The engines keep running during refuelling. Fuel delivered and fuel gained are different quantities.'))
    table([
      ('GROSS ONLOAD',tr('Menge, die vom Tanker in den Receiver übertragen wird. Einheit kg. Das Wort gross bezieht sich hier auf die Lieferung, nicht auf das Flugzeuggewicht.','Fuel transferred from tanker to receiver, in kg. Gross here refers to the delivery, not aircraft gross weight.')),
      ('RECEIVER BURN',tr('Kraftstoffverbrauch des empfangenden Jets. Fuel Flow ist eine Rate in kg/min; Burn ist die über eine Zeit verbrauchte Menge in kg.','Fuel consumed by the receiving jet. Fuel flow is a rate in kg/min; burn is the quantity consumed over a period, in kg.')),
      ('NET GAIN / FOB',tr('Net Gain ist die Zunahme zwischen zwei vergleichbaren Tankständen. FOB ist die gesamte verbleibende Menge an einem bestimmten Zeitpunkt.','Net gain is the increase between two comparable tank readings. FOB is the total fuel remaining at a specified moment.')),
    ],[135,364],[tr('BEGRIFF','TERM'),tr('WAS ER BESCHREIBT','WHAT IT DESCRIBES')])
    formula('FOB OUT = FOB IN + GROSS ONLOAD - EVENT BURN')
    formula('NET GAIN = GROSS ONLOAD - EVENT BURN')
    S.append(Spacer(1,9));S.append(FuelBalance(de));S.append(Spacer(1,10))
    p(tr('Gerundetes Sentinel-Beispiel: 6.256 + 966 - 324 = 6.898 kg. Obwohl 966 kg geliefert werden, beträgt der Zuwachs über das ganze Event nur 642 kg. Wer 966 kg einfach auf FOB IN addiert und den Burn vergisst, plant 324 kg zu viel Weiterflug-Fuel. [7]','Rounded Sentinel example: 6,256 + 966 - 324 = 6,898 kg. Although 966 kg is delivered, fuel increases by only 642 kg across the full event. Adding 966 kg to FOB IN without subtracting burn overstates onward fuel by 324 kg. [7]'))
    h(tr('Messungen: gleiche Start- und Endpunkte verwenden','Measurements: use matching start and end points'))
    p(tr('Aus Tankanzeige und Zeit erhältst du zunächst den Nettozuwachs. Für die Gross-Menge muss der Eigenverbrauch <b>desselben Zeitabschnitts</b> addiert werden. Wenn Burn nur aus einem Modell stammt, bleibt auch die daraus abgeleitete Gross-Rate eine Schätzung. Eine Pause ohne Transfer darf nicht unbemerkt als durchgehende Kontaktzeit zählen.','Tank readings and elapsed time first give net gain. To obtain gross quantity, add receiver burn over <b>that same interval</b>. If burn comes from a model, the derived gross rate remains an estimate. A pause without fuel flow must not silently be treated as continuous transfer time.'))
    formula('Gross rate = (FOB end - FOB start + interval burn) / minutes')
    box(tr('„Gross Fuel“ ist zu ungenau','“Gross fuel” is too ambiguous'),tr('Im Briefing Menge, Rate und Zeitpunkt nennen: „966 kg Gross Onload“ ist eine Lieferung; „488 kg/min Gross Rate“ eine Geschwindigkeit; „FOB OUT 6.898 kg“ das Ergebnis am Event-Ende.','Specify quantity, rate and reference time: “966 kg gross onload” is a delivery; “488 kg/min gross rate” is a flow rate; “FOB OUT 6,898 kg” is the result at event end.'))

    page(17,tr('Transferzeit ist nicht Eventzeit','Transfer time is not event time'),tr('Die Rate beantwortet „wie schnell?“, die Dauer beantwortet „wie lange insgesamt?“.','Rate answers “how fast?”; event duration answers “how long overall?”.'))
    h(tr('Ein Zahlenbeispiel aus dem Bon','An example from the ticket'))
    table([
      (tr('Gesamtes Event','Whole event'),'10.0 min',tr('Verbrauch über den gesamten geplanten Block.','Consumption throughout the planned block.')),
      (tr('Transfer','Fuel transfer'),'1.98 min',tr('Etwa 1 min 59 s mit Fuel-Übertragung; rund 64 kg Receiver Burn.','About 1 min 59 s with fuel flowing; around 64 kg receiver burn.')),
      (tr('Übrige Zeit','Remaining time'),'8.02 min',tr('Modelliert als Orbit-/Restzeit ohne Lieferung; rund 260 kg Burn.','Modeled as orbit/remaining time without delivery; around 260 kg burn.')),
    ],[125,80,294],[tr('PHASE','PHASE'),tr('DAUER','DURATION'),tr('FUEL-FOLGE','FUEL EFFECT')])
    p(tr('Die effektive Gross-Rate von 488,02 kg/min ist im Beispiel deutlich größer als der modellierte Eigenverbrauch von 32,41 kg/min. Während des Transfers steigt FOB daher netto um etwa 455,61 kg/min. Sobald der Transfer endet, sinkt FOB während der Restzeit wieder. Die angezeigten Zahlen sind gerundet. [7]','The example effective gross rate of 488.02 kg/min is much higher than the modeled receiver flow of 32.41 kg/min. During transfer, FOB therefore rises at about 455.61 kg/min net. Once transfer stops, FOB falls again during the remaining time. Displayed values are rounded. [7]'))
    h(tr('Warum TARGET FOB OUT am Ende des Events zählt','Why TARGET FOB OUT belongs at event end'))
    p(tr('Ein gewünschter Zielstand muss nach dem gesamten Event übrig bleiben. Wird nach Kontaktende noch gewartet, gehört dieser Verbrauch dazu. Für konstante Rate R und Receiver Flow F gilt bei vorgegebener Event-Dauer D:','A requested target must remain after the whole event. Waiting after contact consumes additional fuel. With constant transfer rate R, receiver flow F and planned event duration D:'))
    formula('G = max(0, Target OUT - FOB IN + F x D)')
    formula('Transfer time = G / R     (must fit inside D)')
    p(tr('Nur ohne zusätzliche Restzeit ergibt sich für einen positiven erforderlichen Zuwachs t = (Target - FOB IN) / (R - F). Ein gemessenes, fuelabhängiges Ratenprofil wird dagegen abschnittsweise ausgewertet. Diese Erklärung ändert keine App-Formel. [7]','Only when there is no additional time does a positive required gain give t = (Target - FOB IN) / (R - F). A measured rate profile that varies with fuel state is evaluated by segments instead. This explanation changes no app formula. [7]'))
    h(tr('Kapazität am tatsächlichen Höchststand prüfen','Check capacity at the actual peak'))
    p(tr('FOB AFTER LOAD 7.222 kg ist nur IN + Lieferung. Der Transfer-Burn ist bereits währenddessen abgeflossen: rund 7.158 kg am Transferende, danach rund 6.898 kg am Eventende. Im Modell liegt der tatsächliche Peak unter 7.213 kg Kapazität. Eine Wartezeit nach dem Transfer würde einen vorherigen echten Überlauf nicht rückwirkend lösen. [7]','FOB AFTER LOAD 7,222 kg is simply IN + delivery. Transfer burn has already occurred: about 7,158 kg at transfer end, then about 6,898 kg at event end. The modeled actual peak stays below the 7,213 kg capacity. Waiting after transfer would not retroactively fix a genuine earlier overflow. [7]'))
    box(tr('Modellgrenzen sichtbar halten','Keep model limits visible'),tr('N/A / RATE REQUIRED: keine belegte Transferzeit. RATE ≤ RECEIVER FLOW: kein positiver Nettoaufbau in diesem Modell. EVENT TOO SHORT: Zeitbudget reicht nicht. AUTO REFERENCE ESTIMATE: Referenzannahme, keine direkt gemessene Bedingung.','N/A / RATE REQUIRED: no supported transfer time. RATE ≤ RECEIVER FLOW: no positive net gain in this model. EVENT TOO SHORT: insufficient event time. AUTO REFERENCE ESTIMATE: reference assumption, not a directly measured condition.'))

    page(18,tr('Bingo und Joker verstehen','Understand Bingo and Joker'),tr('Fuel-Schwellen sind Entscheidungspunkte mit einem Bezug, keine Tank-Eigenschaften.','Fuel thresholds are decision points with a reference, not properties of a tank.'))
    table([
      ('BINGO',tr('In der US-Multi-Service-Terminologie der vorbesprochene Kraftstoffstand für die Rückkehr/Landung. [3]','In US multi-service terminology, the briefed fuel state required for recovery. [3]')),
      ('JOKER',tr('Ein höherer Stand, bei dem Trennung, Abbruch oder Beenden des Events beginnen soll. Die vereinbarte Folgemaßnahme gehört zum Begriff. [3]','A higher state at which separation, withdrawal or event termination should begin. The briefed follow-on action matters. [3]')),
    ],[80,419],[tr('BEGRIFF','TERM'),tr('BEDEUTUNG','MEANING')])
    p(tr('Die Zahl hängt vom Plan ab. Ein öffentliches USAF-Ausbildungshandbuch beschreibt sogar mehrere Joker-Werte an Übergangspunkten und Anpassungen an geänderte Flugbedingungen. Das ist ein Beispiel für das Briefing-Prinzip, keine Übernahme von T-6-Verbrauchswerten auf einen Eurofighter. [4]','The number depends on the plan. A public USAF training manual describes multiple Joker values at transition points and adjustments for changed flight conditions. This illustrates the briefing principle; it does not transfer T-6 fuel figures to a Eurofighter. [4]'))
    h(tr('Was „Recovery“ hier bedeutet','What “recovery” means here'))
    p(tr('Rückkehr bis zur vorgesehenen Landung, mit den angesetzten Reserven und gegebenenfalls Ausweichplatz. Bingo ist deshalb nicht „Tank fast leer“ und nicht die Landing Reserve allein. Beim Erreichen von Bingo wird die Rückkehr eingeleitet, damit die erforderliche Reserve bei der Landung verbleibt. [4]','Return through the intended landing, with the planned reserves and alternate where applicable. Bingo therefore does not mean “almost empty” or landing reserve alone. Recovery begins at Bingo so that the required reserve remains at landing. [4]'))
    h(tr('Die besondere Umsetzung dieser App','The specific implementation in this app'))
    p(tr('Die App bildet am gewählten Referenz-WP den Bedarf für <b>restliche geplante Mission + Used Divert + Recovery Extra + Landing Reserve</b>. Das ist keine universelle militärische Direkt-RTB-Formel. Wenn direkt nach Hause geflogen werden soll, muss auch der zugrunde gelegte Flugweg dazu passen. [7]','At the selected reference WP, the app accounts for <b>remaining planned mission + Used Divert + Recovery Extra + Landing Reserve</b>. This is not a universal military direct-RTB formula. If the intended action is to fly directly home, the assumed route must match that action. [7]'))
    table([
      ('JOKER @ WP IN',tr('Der geplante Hold am Referenzpunkt steht noch bevor; sein Burn gehört hinein.','The hold at the reference point is still ahead; its burn is included.')),
      ('JOKER @ WP OUT',tr('Dieser Hold ist erledigt; sein Burn darf nicht nochmals addiert werden.','That hold is complete; its burn must not be added again.')),
      ('JOKER BUFFER',tr('Zusätzliche planbare Marge, kein universeller Fixwert und kein Ersatz für Divert/Reserve.','An additional planning margin, not a universal fixed value or a substitute for divert/reserve.')),
    ],[145,354])
    box(tr('Sentinel: eine kleine Marge richtig lesen','Sentinel: interpret a small margin correctly'),tr('FOB S-PUSH IN 6.475 kg gegenüber Joker IN 6.449 kg: nur etwa 26 kg oberhalb der geplanten Schwelle. Das sind nicht 26 kg bis zum leeren Tank. Bingo 1.853 kg ist hier auf Arrival ETSN IN bezogen und darf nicht als identischer Bedarf an jedem Routenpunkt gelesen werden. [7]','S-PUSH IN FOB 6,475 kg versus Joker IN 6,449 kg: only about 26 kg above the planned threshold. That is not 26 kg until an empty tank. Bingo 1,853 kg here is referenced to arrival ETSN IN and must not be read as the same requirement everywhere along the route. [7]'))

    page(19,tr('Tiger und die AAR-Perspektive','Tiger and the AAR perspective'),tr('Was die Begriffe über Bereitschaft sagen - und was die App daraus nicht ableitet.','What the terms say about readiness, and what the app does not infer from them.'))
    h('TIGER / TIGER FUEL')
    p(tr('TIGER meldet genug <b>Kraftstoff und Bewaffnung</b> für einen Commit: die Übernahme eines Einsatz-/Engagement-Auftrags. Eine feste Fuel-Menge nennt die Definition nicht. [3]','TIGER reports sufficient <b>fuel and ordnance</b> to accept a commit: an assigned engagement/task. The definition gives no fixed fuel quantity. [3]'))
    p(tr('Folglich beweist ein voller Tank diesen Status allein nicht. Ein „Tiger Fuel“-Wert muss im Simulator-Briefing erklärt werden.','It follows that a full tank alone does not establish this status. A “Tiger fuel” figure needs an agreed simulator briefing meaning.'))
    box(tr('In dieser App: Hintergrundwissen','In this app: background knowledge'),tr('Die App berechnet Fuel, aber beurteilt keine Bewaffnung und keine Commit-Fähigkeit. Deshalb gibt es hier keinen automatisch berechneten TIGER-Status. BINGO 2 ist ebenfalls kein verstecktes Tiger Fuel. Diese Anleitung ergänzt nur die Erklärung. [7]','The app calculates fuel but does not assess ordnance or ability to accept a commit. It therefore provides no automatically calculated TIGER status. BINGO 2 is not hidden Tiger fuel either. This guide adds explanation only. [7]'))
    h(tr('Realer Bezug: Eurofighter und A330','Real-world context: Typhoon and A330'))
    p(tr('Die RAF beschreibt den Typhoon mit Probe-and-drogue-Betankung. Ihr A330-basierter Voyager nutzt Schlauchsysteme; die Unterflügelstationen sind für Fast Jets vorgesehen. Ein Tankername allein beschreibt also noch keine wirksame Rate am Receiver. Die App verwendet dafür ihre Simulator-Messdaten und gekennzeichneten Modelle, keine reale Leistungsfreigabe. [5, 6, 7]','The RAF describes Typhoon as using probe-and-drogue refuelling. Its A330-based Voyager uses hose systems, with underwing stations for fast jets. A tanker name alone therefore does not specify an effective receiver rate. This app uses simulator measurements and identified models, not real-world performance approval. [5, 6, 7]'))
    h(tr('Was vor einem gemeinsamen Simulatorflug geklärt sein sollte','What to agree before a shared simulator flight'))
    table([
      (tr('Treffpunkt und Uhrzeit','Meeting point and time'),tr('Welcher Punkt ist gemeint? Welche Zeit ist PLAN, welche HARD? Ist ARIP überhaupt definiert?','Which point is meant? Which time is PLAN and which HARD? Is an ARIP defined at all?')),
      (tr('Fuel-Auftrag','Fuel request'),tr('Gross-Menge oder Ziel-FOB am Event-Ende? kg oder lb? Wie viel Zeit ist für das ganze Event geplant?','Gross quantity or target FOB at event end? kg or lb? How much time is allocated to the entire event?')),
      (tr('Rückkehrentscheidung','Recovery decision'),tr('Für welchen WP gelten Joker/Bingo? IN oder OUT? Welcher Divert ist USED, welche Reserve angesetzt?','Which WP does Joker/Bingo apply to? IN or OUT? Which divert is USED and which reserve is planned?')),
      (tr('Wenn AAR ausfällt','If AAR is unavailable'),tr('Als separaten Simulatorfall ohne Onload prüfen. Ein geplanter Transfer ist noch kein gelieferter Kraftstoff.','Check a separate simulator case without onload. Planned transfer is not fuel already delivered.')),
    ],[140,359])

    page(20,tr('Quellen und Einordnung','Sources and scope'),tr('Öffentliche Hintergründe, eigene Rechenbeispiele und App-Verhalten getrennt belegt.','Public background, worked examples and application behaviour are identified separately.'))
    refs=[
      ('1','USAF - AFMAN 11-255, Volume 3','16 Nov 2023, Attachment 1, pp. 42-43','https://static.e-publishing.af.mil/production/1/af_a3/publication/afman11-255v3/afman11-255v3.pdf',tr('Definitionen ARIP, ARCP und verfahrensabhängiger ARCT-Bezug.','ARIP, ARCP and procedure-dependent ARCT definitions.')),
      ('2','FAA - Special Operations, Chapter 5','Section 1, General / Chronology','https://www.faa.gov/air_traffic/publications/atpubs/so_html/chap5_section_1.html',tr('Rendezvous, Koordination und Abgrenzung vom tatsächlichen Transfer.','Rendezvous, coordination and distinction from actual transfer.')),
      ('3','ALSSA - Multi-Service Brevity Codes','25 Apr 2025, Table 2: BINGO p. 5, JOKER p. 25, TIGER p. 50','https://www.alssa.mil/Portals/9/Documents/mttps/brevity_2025.pdf',tr('US-Multi-Service-Bedeutungen. Keine pauschale Gleichsetzung mit jedem NATO- oder nationalen Verfahren.','US multi-service meanings; not assumed identical to every NATO or national procedure.')),
      ('4','USAF - AETCMAN 11-248','13 Aug 2025, section 1.11, Fuel Considerations','https://static.e-publishing.af.mil/production/1/aetc/publication/aetcman11-248/aetcman11-248.pdf',tr('Briefing und veränderliche Joker-/Bingo-Bezüge am Beispiel eines Ausbildungsmusters.','Briefing and variable Joker/Bingo references, illustrated by a training aircraft.')),
      ('5','Royal Air Force - Typhoon FGR4','Aircraft overview / Air-to-Air Refuelling','https://www.raf.mod.uk/aircraft/current-aircraft/typhoon-fgr41/',tr('Probe-and-drogue-System.','Probe-and-drogue system.')),
      ('6','Royal Air Force - Voyager','Aircraft overview / Role','https://www.raf.mod.uk/aircraft/current-aircraft/voyager/',tr('A330-Basis und Schlauchstationen für unterschiedliche Receiver.','A330 basis and hose stations for different receivers.')),
    ]
    for no,title,detail,url,meaning in refs:
        h('['+no+'] '+title)
        p(detail+'<br/>'+meaning+'<br/><link href="'+url+'" color="#54624b">'+tr('Originalquelle öffnen','Open primary source')+'</link>','small')
    h('[7] Eurofighter IFE Fuel Calculator v1.9.23')
    p(tr('App-Code: app.js, logic-core.js, AAR-Profilmodell und optionaler RHINE-SENTINELLE-Preset. Screenshots und Beispielwerte aus der offiziellen Web-App. Formeln und Erläuterungen in diesem Handbuch sind eigene Darstellungen des implementierten Modells.','Application code: app.js, logic-core.js, AAR profile model and optional RHINE SENTINELLE preset. Screenshots and worked values from the official web app. Equations and explanations are original descriptions of the implemented model.'),'small')
    box(tr('Geltungsbereich','Scope'),tr('Geprüft am 12.10.2026. Hintergrundkapitel dienen dem Verständnis für MSFS / IndiaFoxtEcho. Nationale Verfahren und konkrete Briefings können abweichen. Keine reale Eurofighter-Flug-, Betankungs- oder Einsatzfreigabe. App-Logik, Missionswerte und Default bleiben unverändert.','Checked 12 Oct 2026. These background chapters explain concepts for MSFS / IndiaFoxtEcho. National procedures and specific briefings may differ. This is not real-world Eurofighter flight, refuelling or mission authorization. App logic, mission values and defaults remain unchanged.'))
